    void addRecordings(){if(project.clips.size()>=30){message("Maximum 30 clips");return;}List<java.io.File> available=new ArrayList<>();for(java.io.File file:new ClipStore(this).clips())if(ClipStore.finalized(file)&&(!project.pip||file.getName().startsWith("rear-")))available.add(file);if(available.isEmpty()){message("No finalized recordings available");return;}String[] names=new String[available.size()];for(int i=0;i<names.length;i++){java.io.File f=available.get(i);names[i]=new java.text.SimpleDateFormat("dd MMM HH:mm",Locale.getDefault()).format(new Date(f.lastModified()))+" · "+f.getName();}List<String> selectedPaths=new ArrayList<>();new AlertDialog.Builder(this).setTitle("Add recordings").setMultiChoiceItems(names,null,(dialog,index,checked)->{if(checked){if(project.clips.size()+selectedPaths.size()>=30){((AlertDialog)dialog).getListView().setItemChecked(index,false);message("Maximum 30 clips");}else selectedPaths.add(available.get(index).getPath());}else selectedPaths.remove(available.get(index).getPath());}).setPositiveButton("Add",(dialog,which)->{if(selectedPaths.isEmpty())return;status.setText("Opening selected recordings…");new Thread(()->{try{SocialProject extra=SocialProject.load(this,SocialProject.selection(selectedPaths));runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(project.clips.size()+extra.clips.size()>30||project.durationMs()+extra.durationMs()>SocialProject.MAX_DURATION_MS){message("Use at most 30 clips and two hours");return;}remember();int index=project.clips.size();project.clips.addAll(extra.clips);selected=index;seekMs=startOf(index);clipToolsVisible=true;tool="Clips";refresh();});}catch(Exception error){runOnUiThread(()->message(error.getMessage()));}},"DashStudioAppend").start();}).setNegativeButton("Cancel",null).show();}
