    void customData(){String[] keys={"speed","time","distance","route","altitude","heading","accuracy","battery","camera"};boolean[] on=new boolean[keys.length];for(int i=0;i<keys.length;i++)on[i]=recipe.number("social_overlay",0)==4?recipe.number("overlay_"+keys[i],i==0||i==1||i==3?1:0)==1:SocialProfile.overlay(recipe.number("social_overlay",0),keys[i]);new AlertDialog.Builder(this).setTitle("Recorded ride data").setMultiChoiceItems(keys,on,(d,i,v)->on[i]=v).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{remember();setting("social_overlay",4);for(int i=0;i<keys.length;i++)setting("overlay_"+keys[i],on[i]?1:0);refresh();}).show();}
    void colour(){choice("Accent / text colour",new String[]{"RideDeck blue","White","Amber","Mint","Pink"},i->setting("studio_color",new int[]{0xff6284ff,Color.WHITE,0xffff8340,0xff7be6b7,0xffffa9d7}[i]));}
    void editText(){EditText value=new EditText(this);value.setText(recipe.text("studio_text",""));value.setHint("Your ride title or caption");value.setMaxLines(4);value.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(200)});new AlertDialog.Builder(this).setTitle("Title / caption").setView(value).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{remember();setting("studio_text",value.getText().toString());refresh();}).show();}
    void textTiming(){rangeDialog("Text appears / disappears, seconds",recipe.number("studio_text_start",0),Math.min(project.durationMs(),recipe.number("studio_text_end",(int)project.durationMs())),project.durationMs(),(a,b)->{setting("studio_text_start",(int)a);setting("studio_text_end",(int)b);});}
    interface RangeAction{void apply(long a,long b);}
    void rangeDialog(String title,long start,long end,long limit,RangeAction action){LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);EditText from=new EditText(this),to=new EditText(this);from.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);to.setInputType(from.getInputType());from.setHint("Start seconds");to.setHint("End seconds");from.setText(seconds(start));to.setText(seconds(end));fields.addView(from);fields.addView(to);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{long a=parseMs(from.getText().toString()),b=parseMs(to.getText().toString());if(a<0||b>limit||b-a<500)throw new IllegalArgumentException();remember();action.apply(a,b);dialog.dismiss();refresh();}catch(Exception e){to.setError("Choose at least 0.5s within "+seconds(limit)+"s");}}));dialog.show();}
    void trim(int i){SocialProject.Clip clip=project.clips.get(i);rangeDialog("Trim clip "+(i+1),clip.fromMs,clip.toMs,clip.durationMs,(a,b)->{clip.fromMs=a;clip.toMs=b;seekMs=startOf(i);});}
    void syncOffset(){EditText value=new EditText(this);value.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);value.setText(""+project.shiftMs);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Front delay, milliseconds (-5000 to 5000)").setView(value).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{int n=Integer.parseInt(value.getText().toString());if(Math.abs((long)n)>5000)throw new IllegalArgumentException();remember();project.shiftMs=n;dialog.dismiss();refresh();}catch(Exception e){value.setError("Enter -5000 to 5000");}}));dialog.show();}
    long startOf(int i){long n=0;for(int j=0;j<i;j++)n+=project.clips.get(j).lengthMs();return n;}
    int clipAt(long time){long end=0;for(int i=0;i<project.clips.size();i++){end+=project.clips.get(i).lengthMs();if(time<end)return i;}return project.clips.size()-1;}
    void split(){long output=playRequested&&player!=null?player.getCurrentPosition():seekMs;int index=clipAt(output);SocialProject.Clip clip=project.clips.get(index);long time=output-startOf(index)+clip.fromMs;if(time-clip.fromMs<500||clip.toMs-time<500){message("Place the playhead inside this clip, at least 0.5s from either edge");return;}if(project.clips.size()>=30){message("Maximum 30 clips");return;}remember();long old=clip.toMs;clip.toMs=time;project.clips.add(index+1,new SocialProject.Clip(clip.file,clip.durationMs,time,old));selected=index+1;seekMs=output;clipToolsVisible=true;refresh();message("Split into two clips. No footage removed.");}
    void move(int direction){remember();Collections.swap(project.clips,selected,selected+direction);selected+=direction;seekMs=startOf(selected);refresh();}
    Bundle snapshot(){Bundle b=new Bundle();b.putBundle("project",project.bundle());b.putBundle("recipe",recipe.bundle());b.putInt("selected",selected);b.putLong("seek",seekMs);b.putBoolean("clipTools",clipToolsVisible);return b;}
    void remember(){if(playRequested&&player!=null)seekMs=player.getCurrentPosition();playRequested=false;if(player!=null)player.pause();undo.addLast(snapshot());while(undo.size()>30)undo.removeFirst();redo.clear();}
    void history(boolean forward){ArrayDeque<Bundle> from=forward?redo:undo,to=forward?undo:redo;if(from.isEmpty())return;to.addLast(snapshot());Bundle b=from.removeLast();try{project=SocialProject.load(this,b.getBundle("project"));recipe=DashSettings.fromBundle(this,b.getBundle("recipe"));selected=b.getInt("selected");seekMs=b.getLong("seek");clipToolsVisible=b.getBoolean("clipTools");playRequested=false;refresh();}catch(Exception e){message(e.getMessage());}}
    void save(boolean notify){if(project==null||draftDiscarded)return;try{StudioDrafts.save(this,draftId,project.bundle(),recipe.bundle());if(notify)message("Draft saved. Original recordings are unchanged.");}catch(Exception e){message("Could not save draft: "+e.getMessage());}}
    void drafts(){save(false);StudioDraftPicker.show(this,id->{startActivity(new Intent(this,SocialStudioActivity.class).putExtra("draft",id));finish();},this::draftsDeleted,()->{draftId=UUID.randomUUID().toString();save(true);});}

    void draftsDeleted(List<String> ids){if(ids.contains(draftId)){draftDiscarded=true;finish();}}
    void exportOptions(){if(RecordingService.running||RecordingService.finalizing){message("Stop recording before editing or exporting");return;}String[] modes={"One merged video","Separate social videos"};new AlertDialog.Builder(this).setTitle("Export · "+seconds(project.durationMs())+"s · about "+(project.durationMs()*recipe.number("social_bitrate",8)/8000)+" MB").setItems(new String[]{modes[project.merge?0:1],"Change merge / batch mode","Quality: "+recipe.number("social_quality",1080)+"p","Save draft"},(d,i)->{if(i==0){save(false);startActivity(new Intent(this,SocialExportActivity.class).putExtra("project",project.bundle()).putExtra("recipe",recipe.bundle()));}else if(i==1)choice("Export mode",modes,n->project.merge=n==0);else if(i==2)choice("Export quality",new String[]{"720p · smaller · 4 Mbps","1080p · clear · 8 Mbps","1080p · high · 16 Mbps"},n->{setting("social_quality",n==0?720:1080);setting("social_bitrate",new int[]{4,8,16}[n]);});else save(true);}).setMessage(null).setNegativeButton("Cancel",null).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{Uri uri=data.getData();getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);remember();setting("studio_music",uri.toString());String name="Selected audio";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}setting("studio_music_name",name);refresh();}catch(Exception e){message("Cannot use this audio file: "+e.getMessage());}}}
    void refresh(){if(project==null)return;prepared=null;handler.removeCallbacks(timelineSeek);timelineScrubbing=false;int[] canvasSize=SocialProfile.dimensions(recipe.number("social_ratio",0),recipe.number("social_quality",1080));previewCanvas.setAspectRatio(canvasSize[0]/(float)canvasSize[1]);selected=Math.max(0,Math.min(selected,project.clips.size()-1));seekMs=Math.max(0,Math.min(seekMs,project.durationMs()));timeline.bind(project,selected);timeline.post(this::centerPlayhead);scrub.setMax((int)project.durationMs());positions.invalidate();showTool();save(false);prepare();}
    int segmentAt(long ms){return previewCuts.headSet(ms,true).size();}
    void togglePlay(){if(player!=null&&player.getPlaybackState()==Player.STATE_ENDED){seekPreview(0);playRequested=true;if(player!=null)player.play();return;}playRequested=!playRequested;if(player!=null){if(playRequested)player.play();else player.pause();}}
    void seekPreview(long time){handler.removeCallbacks(timelineSeek);timelineScrubbing=false;playRequested=false;if(player!=null)player.pause();seekMs=Math.max(0,Math.min(Math.max(0,project.durationMs()-1),time));centerPlayhead();if(project.pip){prepare();}else if(player!=null)player.seekTo(seekMs);}
    void prepare(){
        final int request=++generation;release();firstFrameRendered=false;export.setEnabled(false);
        if(RecordingService.running||RecordingService.finalizing){status.setText("Stop recording before editing or exporting");return;}
        status.setText(recipe.number("studio_stabilize",0)>0?"Analyzing stabilization and preparing preview…":"Preparing preview…");final Bundle spec=project.bundle();final DashSettings frozen=recipe;final SocialComposition.Built cached=prepared;
        new Thread(()->{try{SocialProject snapshot=SocialProject.load(this,spec);SocialComposition.Built built=cached!=null?cached:SocialComposition.build(this,snapshot,frozen,false,()->generation!=request||RecordingService.running||RecordingService.finalizing);
            runOnUiThread(()->{if(generation!=request||isFinishing()||isDestroyed())return;try{prepared=built;CompositionPlayer.Builder playback=new CompositionPlayer.Builder(this);if(snapshot.pip)playback.setVideoGraphFactory(new MultipleInputVideoGraph.Factory());player=playback.build();preview.setPlayer(player);player.addListener(new Player.Listener(){@Override public void onRenderedFirstFrame(){if(generation==request){firstFrameRendered=true;export.setEnabled(true);if(playRequested)player.play();}}@Override public void onPlayerError(PlaybackException e){if(generation==request){export.setEnabled(false);status.setText("Preview failed: "+e.getErrorCodeName());}}});previewCuts.clear();if(snapshot.pip)for(androidx.media3.transformer.EditedMediaItemSequence sequence:built.composition.sequences){if(!sequence.trackTypes.contains(C.TRACK_TYPE_VIDEO))continue;long end=0;for(androidx.media3.transformer.EditedMediaItem item:sequence.editedMediaItems){end+=((item.mediaItem.clippingConfiguration.endPositionUs==C.TIME_END_OF_SOURCE?item.durationUs:item.mediaItem.clippingConfiguration.endPositionUs)-item.mediaItem.clippingConfiguration.startPositionUs)/1000;if(end<built.durationMs)previewCuts.add(end);}}previewSegment=segmentAt(seekMs);player.setComposition(built.composition,seekMs);player.prepare();
                status.setText((frozen.number("studio_stabilize",0)>0?"Stabilized preview · ":"Ready · ")+snapshot.clips.size()+" clips · originals kept"+(snapshot.pip&&built.missingFrontMs>0?" · front gaps "+seconds(built.missingFrontMs)+"s":""));
            }catch(Exception e){release();status.setText("Preview unavailable: "+e.getMessage());}});
        }catch(Exception e){runOnUiThread(()->{if(generation==request)status.setText("Preview unavailable: "+e.getMessage());});}},"DashStudioPrepare").start();
    }
    final Runnable tick=new Runnable(){public void run(){if(project==null||!resumed)return;if(RecordingService.running||RecordingService.finalizing){generation++;release();export.setEnabled(false);status.setText("Preview stopped for recording");}if(player!=null&&!scrubbing&&!timelineScrubbing){seekMs=player.getCurrentPosition();if(project.pip&&player.getPlaybackState()!=Player.STATE_ENDED&&segmentAt(seekMs)!=previewSegment){prepare();}else{if(!scrub.isPressed())scrub.setProgress((int)seekMs);if(player.getPlaybackState()==Player.STATE_ENDED)playRequested=false;play.setText(playRequested?"Ⅱ":"▶");play.setContentDescription(playRequested?"Pause preview":"Play preview");timeline.playhead=seekMs;if(playRequested)centerPlayhead();timeline.invalidate();}}clock.setText(time(seekMs)+" / "+time(project.durationMs()));handler.postDelayed(this,200);}};
    static String time(long ms){return String.format(Locale.ROOT,"%02d:%02d",ms/60000,ms/1000%60);}
    static String seconds(long ms){return java.math.BigDecimal.valueOf(ms,3).stripTrailingZeros().toPlainString();}
    static long parseMs(String value){return new java.math.BigDecimal(value.trim()).movePointRight(3).longValueExact();}
    void message(String value){Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
    void release(){if(player!=null){preview.setPlayer(null);player.release();player=null;}}
    @Override protected void onSaveInstanceState(Bundle b){if(project!=null||openingSpec!=null){b.putBundle("project",project!=null?project.bundle():openingSpec);b.putBundle("recipe",recipe.bundle());b.putString("draft",draftId);b.putInt("selected",selected);b.putLong("seek",seekMs);b.putString("tool",tool);b.putBoolean("clipTools",clipToolsVisible);}super.onSaveInstanceState(b);}
    @Override protected void onStop(){resumed=false;save(false);generation++;handler.removeCallbacksAndMessages(null);release();super.onStop();}
    @Override protected void onDestroy(){generation++;release();if(timeline!=null)timeline.close();super.onDestroy();}
    final class PositionLayer extends View {
        final Paint p=new Paint(3);float x,y;boolean dragging;
        PositionLayer(){super(SocialStudioActivity.this);setContentDescription("Overlay position canvas");}
        RectF canvas(){int[] size=SocialProfile.dimensions(recipe.number("social_ratio",0),recipe.number("social_quality",1080));float scale=Math.min(getWidth()/(float)size[0],getHeight()/(float)size[1]),w=size[0]*scale,h=size[1]*scale;return new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);}
        @Override protected void onDraw(Canvas c){RectF r=canvas();if(tool.equals("Clips")&&clipToolsVisible){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(0xffffbf69);c.drawRect(r,p);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(0x6690c8ff);if(guides&&tool.equals("Crop")){c.drawRect(r.left+r.width()*.05f,r.top+r.height()*.09f,r.right-r.width()*.16f,r.bottom-r.height()*.21f,p);}if(!target.isEmpty()){int a=target.equals("crop")?50:target.equals("pip")?Math.max(3,project.pipX):recipe.number("studio_"+target+"_x",8),b=target.equals("crop")?50:target.equals("pip")?Math.max(3,project.pipY):recipe.number("studio_"+target+"_y",35);p.setColor(0xffffbf69);float px=r.left+r.width()*a/100,py=r.top+r.height()*b/100;c.drawCircle(px,py,dp(12),p);p.setStyle(Paint.Style.FILL);p.setTextSize(dp(12));c.drawText("Move "+target,px+dp(16),py,p);}}
        @Override public boolean onTouchEvent(MotionEvent e){if(target.isEmpty())return false;RectF r=canvas();if(r.width()<=0||r.height()<=0)return false;if(e.getAction()==MotionEvent.ACTION_DOWN){remember();dragging=true;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE||e.getAction()==MotionEvent.ACTION_UP){if(!dragging)return false;int a=Math.max(0,Math.min(85,Math.round((e.getX()-r.left)/r.width()*100))),b=Math.max(0,Math.min(85,Math.round((e.getY()-r.top)/r.height()*100)));if(target.equals("crop")){setting("studio_pan_x",Math.max(-100,Math.min(100,Math.round((e.getX()-r.centerX())/r.width()*200))));setting("studio_pan_y",Math.max(-100,Math.min(100,Math.round((e.getY()-r.centerY())/r.height()*200))));}else if(target.equals("pip")){project.pipX=a;project.pipY=b;}else{setting("studio_"+target+"_x",a);setting("studio_"+target+"_y",b);}invalidate();if(e.getAction()==MotionEvent.ACTION_UP){dragging=false;performClick();refresh();}return true;}if(e.getAction()==MotionEvent.ACTION_CANCEL){dragging=false;return true;}return true;}
        @Override public boolean performClick(){super.performClick();return true;}
    }
